(function(){'use strict';const $=id=>document.getElementById(id);try{
 const data=Voces.validate(window.VOCES_DATA),visuals=Voces.initVisuals(data);Voces.initLearning();Voces.initScenarios(data);Voces.initExport(data);const contrasts=Voces.initContrasts(data);
 $('loadStatus').hidden=true;$('participationStory').setAttribute('aria-live','polite');$('stateComparison').setAttribute('aria-live','polite');
 const sections=['historia','tiempo','territorio','aprender','escenarios','compartir'];
 const quick=['60 puntos ilustran 59,7 %. El número mantiene el decimal de la fuente; el dibujo redondea.','Compara elecciones del mismo tipo. De 2018 a 2024, la diferencia es −2,7 puntos porcentuales.','Compara ocho entidades o explora los 18 grupos de edad de 2024. Son vistas independientes: una diferencia no explica los motivos de cada persona.','Comprueba lo aprendido. Cada respuesta explica una idea; el resultado se queda en este navegador.','Compara los escenarios A y B con el dato observado. Sus diferencias son cuentas hipotéticas, no predicciones ni efectos de políticas.','Elige un formato, descarga un PNG y acompáñalo de su descripción accesible. La fuente viaja con el dato.'];
 const jury=['0:00–0:30 · Promesa: traducir los CCPC en conocimiento comprensible. Cambia 2024 por 2018 y revela evidencia.','0:30–1:00 · Muestra −2,7 pp entre presidenciales y +4,7 pp entre intermedias. Explica la diferencia entre dato y causa.','1:00–1:25 · Selecciona Veracruz. Compara su tasa con la nacional y declara el alcance de ocho entidades.','1:25–1:50 · Responde una pregunta. Destaca retroalimentación, accesibilidad y ausencia de registro de usuarios.','1:50–2:15 · Mueve el escenario en ambas direcciones. Señala explícitamente que no es una predicción.','2:15–2:55 · Genera una tarjeta con fuente y texto accesible. Cierra: Los datos ya hablan. Hagamos que se entiendan.'];
 let tourAt=0,mode='quick',returnFocus=null;
 function showTour(){const target=$(sections[tourAt]);$('tourTitle').textContent=`${mode==='quick'?'60 segundos':'Presentación · 3 min'} · ${tourAt+1} / 6`;$('tourText').textContent=(mode==='quick'?quick:jury)[tourAt];$('tourBack').disabled=tourAt===0;$('tourNext').textContent=tourAt===5?'Terminar recorrido':'Siguiente →';target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
 function closeTour(){$('tour').hidden=true;document.body.classList.remove('tour-active');returnFocus?.focus({preventScroll:true});}
 function begin(m,button){mode=m;tourAt=0;returnFocus=button;$('tour').hidden=false;document.body.classList.add('tour-active');visuals.setYear(2024);visuals.kind('presidencial');contrasts.view('states');showTour();$('tourNext').focus({preventScroll:true});}
 $('quickMode').onclick=e=>begin('quick',e.currentTarget);$('juryMode').onclick=e=>begin('jury',e.currentTarget);$('tourNext').onclick=()=>{if(tourAt===5)closeTour();else{tourAt++;showTour();}};$('tourBack').onclick=()=>{if(tourAt>0){tourAt--;showTour();}};$('tourClose').onclick=closeTour;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('tour').hidden)closeTour();});$('printLesson').onclick=()=>window.print();
 document.documentElement.dataset.ready='true';
}catch(err){$('loadStatus').hidden=false;$('loadStatus').textContent='Datos no disponibles: '+err.message+' Revisa el archivo de datos y vuelve a cargar la página.';document.querySelectorAll('main button,main select,main input').forEach(el=>el.disabled=true);document.querySelectorAll('#participationValue,#splitYes,#splitNo,#stateValue,#statePercent,#scenarioOutput').forEach(el=>el.textContent='No disponible');document.documentElement.dataset.ready='error';console.error(err);}})();
